checks.command:
node --input-type=module - <<'JS'
import fs from 'node:fs/promises';
import {hash} from './measure-test-quality/scripts/core.mjs';
const r=JSON.parse(await fs.readFile('artifacts/measurement.json'));
for(const stage of ['initial','final']) for(const [name,expected] of Object.entries(r[stage].frozen.runnerSha256)) {
 if(hash(await fs.readFile('measure-test-quality/scripts/'+name))!==expected) throw new Error('runner changed: '+name);
}
const official=JSON.parse(await fs.readFile('artifacts/official-checker.json'));
for(const i of official.inputs.filter(i=>i.path.startsWith('measure-test-quality/'))) if(hash(await fs.readFile(i.path))!==i.sha256) throw new Error('checked skill changed');
console.log('Current runner hashes match both campaigns; skill/reference hashes match official validation.');
JS
